def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    A = [[Fraction(matrix[i][j]) for j in range(n)] for i in range(n)]
    sign = 1
    for k in range(n):
        pivot_row = None
        for i in range(k, n):
            if A[i][k] != 0:
                pivot_row = i
                break
        if pivot_row is None:
            return 0
        if pivot_row != k:
            A[k], A[pivot_row] = A[pivot_row], A[k]
            sign = -sign
        pivot = A[k][k]
        for i in range(k + 1, n):
            if A[i][k] != 0:
                factor = A[i][k] / pivot
                for j in range(k, n):
                    A[i][j] -= factor * A[k][j]
    det = Fraction(sign)
    for k in range(n):
        det *= A[k][k]
    return int(det)

